import{_ as a,o as l,c as i,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Keynote- Growing Ceph Knowledge in the User + Developer Community - Laura Flores & Neha Ojha","description":"","frontmatter":{"title":"Keynote- Growing Ceph Knowledge in the User + Developer Community - Laura Flores & Neha Ojha","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["Ceph 用户社区","开发者协作","Ceph 用户故事","Ceph User Council","Ceph 知识共享"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Keynote_-_Growing_Ceph_Knowledge_in_the_User_+_Developer_Community_-_Laura_Flores_Neha_Ojha.md","filePath":"posts/2025/Keynote_-_Growing_Ceph_Knowledge_in_the_User_+_Developer_Community_-_Laura_Flores_Neha_Ojha.md","lastUpdated":1780459816000}'),r={name:"posts/2025/Keynote_-_Growing_Ceph_Knowledge_in_the_User_+_Developer_Community_-_Laura_Flores_Neha_Ojha.md"};function t(h,e,n,_,s,p){return l(),i("div",null,[...e[0]||(e[0]=[o('<p>Ceph 用户与开发者协作会议纪要</p><h3 id="会议基本信息" tabindex="-1">会议基本信息 <a class="header-anchor" href="#会议基本信息" aria-label="Permalink to &quot;会议基本信息&quot;">​</a></h3><ul><li><strong>主持人</strong>：Laura Flores（IBM 软件工程师，RADOS 团队成员）</li><li><strong>共同发言人</strong>：Neha Ojha（Ceph 核心团队成员）</li><li><strong>会议主题</strong>：Ceph 社区知识共享与用户-开发者协作</li><li><strong>会议形式</strong>：线上（Jitsi 视频会议）</li><li><strong>频率</strong>：每月一次（每月第三个星期三，美国东部时间上午 10:00）</li></ul><h3 id="核心讨论议题" tabindex="-1">核心讨论议题 <a class="header-anchor" href="#核心讨论议题" aria-label="Permalink to &quot;核心讨论议题&quot;">​</a></h3><h4 id="用户与开发者协作的重要性" tabindex="-1">用户与开发者协作的重要性 <a class="header-anchor" href="#用户与开发者协作的重要性" aria-label="Permalink to &quot;用户与开发者协作的重要性&quot;">​</a></h4><ul><li>用户反馈帮助开发者识别并优先处理关键问题，如性能调优和 CRUSH 算法改进。</li><li>知识共享，如 CephFS、RBD、RADOSGW 等组件的疑问解答和实际用例反馈。</li><li>协作推动性能、编排等领域的优化，促进社区采纳率提升。</li></ul><h4 id="月度用户-开发者交流会" tabindex="-1">月度用户+开发者交流会 <a class="header-anchor" href="#月度用户-开发者交流会" aria-label="Permalink to &quot;月度用户+开发者交流会&quot;">​</a></h4><ul><li>目标：将用户反馈转化为具体行动项，通过博客、用例分享提升社区知识水平，覆盖所有经验水平的用户。</li><li>近期成果：从 Ceph Days Geneva 2024 用户讨论中提炼了 6 项行动项，已有 15 个跟踪项通过会议推动解决。</li></ul><h4 id="ceph-用户委员会" tabindex="-1">Ceph 用户委员会 <a class="header-anchor" href="#ceph-用户委员会" aria-label="Permalink to &quot;Ceph 用户委员会&quot;">​</a></h4><ul><li>背景：2020 年 COVID 期间启动，2024 年正式结构化。</li><li>核心支柱：性能、编排、质量、可扩展性、可用性。</li><li>运作方式：通过定向调查收集反馈，并在会议中讨论生成行动项。目前由 IBM 和 Bloomberg 主导。</li></ul><h4 id="ceph-用户故事项目" tabindex="-1">Ceph 用户故事项目 <a class="header-anchor" href="#ceph-用户故事项目" aria-label="Permalink to &quot;Ceph 用户故事项目&quot;">​</a></h4><ul><li>目标：更新官网用例页面，展示大规模生产环境中的 Ceph 实践。</li><li>进展：2024 年 9 月启动，收到 84 份用户调查回复，下一步将与 Ceph 大使合作，将用例转化为博客文章。</li></ul><h3 id="关键行动项" tabindex="-1">关键行动项 <a class="header-anchor" href="#关键行动项" aria-label="Permalink to &quot;关键行动项&quot;">​</a></h3><ol><li>修复 Balancer 与 upmap remap 脚本问题，并将其官方集成到 Ceph 代码库。</li><li>持续更新文档，如 RADOS 配置指南。</li><li>招募更多成员领导其他支柱，如加密、灾备。</li><li>完成至少 5 篇新用例博客。</li></ol><h3 id="后续计划" tabindex="-1">后续计划 <a class="header-anchor" href="#后续计划" aria-label="Permalink to &quot;后续计划&quot;">​</a></h3><ul><li>加入月度会议，了解最新动态。</li><li>联系 Laura Flores 或 Neha Ojha 讨论领导用户委员会支柱。</li><li>鼓励社区成员传播会议信息，避免仅依赖线下活动反馈。</li></ul>',16)])])}const c=a(r,[["render",t]]);export{d as __pageData,c as default};
